import type { ApiClient } from "@schoolos/api-client";
import { unwrap } from "@/lib/bff/query";
import * as z from "@/lib/zod";

/**
 * Safety drills and periodic checks (FC-09; FR-COMP-046..FR-COMP-055) and the policy library
 * with staff acknowledgement (FC-10; FR-COMP-056..FR-COMP-070).
 *
 * The routes are new in this wave and not yet in the generated client (`packages/api-client`
 * is regenerated by the lead). Until then these calls go through a loose view of the same
 * openapi-fetch client (same BFF, CSRF, session and step-up handling) and every answer is
 * checked with the zod schemas below. After regeneration, swap `loose(api)` for `api` and the
 * zod types for `components["schemas"][...]` (`ChecksOverviewOut`, `PoliciesOut`, ...).
 */

export const COMPLIANCE_READ = "compliance.read";
export const COMPLIANCE_MANAGE = "compliance.manage";
export const SAFETY_KEYS = {
  checks: ["staff", "compliance", "checks"] as const,
  policies: ["staff", "compliance", "policies"] as const,
  policy: (id: string) => ["staff", "compliance", "policies", id] as const,
  mine: ["staff", "compliance", "my-policies"] as const,
};

interface LooseInit {
  params?: { path?: Record<string, string>; query?: Record<string, string> };
  body?: unknown;
  headers?: Record<string, string>;
}
type LooseResult = Promise<{ data?: unknown; error?: unknown; response: Response }>;
interface LooseClient {
  GET: (path: string, init?: LooseInit) => LooseResult;
  POST: (path: string, init?: LooseInit) => LooseResult;
  PUT: (path: string, init?: LooseInit) => LooseResult;
}

/** The same client, without the generated path types (see the module note). */
function loose(api: ApiClient): LooseClient {
  return api as unknown as LooseClient;
}

async function call<T extends z.ZodType>(schema: T, pending: LooseResult): Promise<z.output<T>> {
  return schema.parse(await unwrap(pending));
}

export function ifMatch(version: number): string {
  return `W/"${version}"`;
}

function text(value: string | undefined): string | null {
  const out = value?.trim();
  return out ? out : null;
}

// --- answers --------------------------------------------------------------------------------

const memberRef = z.object({
  membership_id: z.string(),
  display_name: z.string().nullable(),
  active: z.boolean(),
});
const documentRef = z.object({ id: z.string(), title: z.string().nullable() });

export const checkStateSchema = z.enum(["ok", "due_soon", "overdue", "never", "logged"]);
export type CheckState = z.output<typeof checkStateSchema>;

const checkEntry = z.object({
  id: z.string(),
  kind: z.string(),
  kind_label: z.string(),
  label: z.string().nullable(),
  done_on: z.string(),
  led_by: memberRef.nullable(),
  participants_count: z.number().nullable(),
  duration_minutes: z.number().nullable(),
  result: z.enum(["ok", "action_needed"]),
  observations: z.string().nullable(),
  document: documentRef.nullable(),
  status: z.enum(["recorded", "removed"]),
  recorded_by_name: z.string().nullable(),
  created_at: z.string(),
  version: z.number(),
});
export type CheckEntry = z.output<typeof checkEntry>;

const checkStatus = z.object({
  kind: z.string(),
  kind_label: z.string(),
  every_months: z.number().nullable(),
  drill: z.boolean(),
  state: checkStateSchema,
  last_done_on: z.string().nullable(),
  next_due: z.string().nullable(),
  days_left: z.number().nullable(),
  last_entry_id: z.string().nullable(),
});
export type CheckStatus = z.output<typeof checkStatus>;

const checkKind = z.object({
  kind: z.string(),
  label: z.string(),
  every_months: z.number().nullable(),
  drill: z.boolean(),
  note: z.string(),
  applies: z.boolean(),
});
export type CheckKind = z.output<typeof checkKind>;

export const checksOverviewSchema = z.object({
  statuses: z.array(checkStatus),
  counts: z.object({
    overdue: z.number(),
    due_soon: z.number(),
    never: z.number(),
    ok: z.number(),
  }),
  recent: z.array(checkEntry),
  kinds: z.array(checkKind),
  due_soon_days: z.number(),
  verified: z.boolean(),
  today: z.string(),
  leaders: z.array(memberRef),
});
export type ChecksOverview = z.output<typeof checksOverviewSchema>;

export const reviewStateSchema = z.enum(["ok", "due_soon", "overdue"]);
export type ReviewState = z.output<typeof reviewStateSchema>;
const policyRole = z.object({ role: z.string(), name: z.string() });
export type PolicyRole = z.output<typeof policyRole>;

const policyFields = {
  id: z.string(),
  title: z.string(),
  document: documentRef.nullable(),
  current_version_id: z.string().nullable(),
  ack_roles: z.array(policyRole),
  review_due: z.string(),
  review_state: reviewStateSchema,
  days_left: z.number(),
  last_reviewed_on: z.string().nullable(),
  status: z.enum(["active", "retired"]),
  targeted: z.number(),
  acknowledged: z.number(),
  ack_requested_at: z.string().nullable(),
  created_at: z.string(),
  updated_at: z.string(),
  version: z.number(),
};
export const policySchema = z.object(policyFields);
export type Policy = z.output<typeof policySchema>;

export const policyDetailSchema = z.object({
  ...policyFields,
  members: z.array(
    z.object({
      membership_id: z.string(),
      display_name: z.string(),
      roles: z.array(z.string()),
      acknowledged_at: z.string().nullable(),
      acknowledged_earlier: z.boolean(),
    }),
  ),
});
export type PolicyDetail = z.output<typeof policyDetailSchema>;
export type PolicyMember = PolicyDetail["members"][number];

export const policiesSchema = z.object({
  items: z.array(policySchema),
  counts: z.object({ overdue: z.number(), due_soon: z.number(), pending_acks: z.number() }),
  roles: z.array(policyRole),
  review_months: z.number(),
  verified: z.boolean(),
  today: z.string(),
});
export type Policies = z.output<typeof policiesSchema>;

const myPolicy = z.object({
  id: z.string(),
  title: z.string(),
  current_version_id: z.string().nullable(),
  acknowledged_at: z.string().nullable(),
  needs_ack: z.boolean(),
});
export type MyPolicy = z.output<typeof myPolicy>;
export const myPoliciesSchema = z.object({ items: z.array(myPolicy), pending: z.number() });
export type MyPolicies = z.output<typeof myPoliciesSchema>;

const policyFile = z.object({
  url: z.string(),
  expires_at: z.string(),
  document_version_id: z.string(),
});
export type PolicyFile = z.output<typeof policyFile>;

// --- forms ----------------------------------------------------------------------------------

const count = (max: number) =>
  z
    .string()
    .optional()
    .refine((v) => !v || (/^\d+$/.test(v) && Number(v) <= max), { error: "invalidNumber" });

/** The "log a check" dialog (FR-COMP-048); empty strings mean "not given". */
export const checkFormSchema = z.object({
  kind: z.string().min(1, { error: "chooseOption" }),
  label: z.string().max(120, { error: "tooLong" }).optional(),
  done_on: z.string().min(1, { error: "required" }),
  led_by_membership_id: z.string().optional(),
  participants_count: count(20000),
  duration_minutes: count(1440),
  result: z.enum(["ok", "action_needed"]).optional(),
  observations: z.string().max(500, { error: "tooLong" }).optional(),
  document_id: z.string().optional(),
});
export type CheckInput = z.output<typeof checkFormSchema>;

function whole(value: string | undefined): number | null {
  const out = text(value);
  return out === null ? null : Number(out);
}

/** The body of POST /compliance/checks/entries: drill counts only for drill kinds. */
export function checkBody(input: CheckInput, drill: boolean) {
  return {
    kind: input.kind,
    label: input.kind === "other" ? text(input.label) : null,
    done_on: input.done_on,
    led_by_membership_id: text(input.led_by_membership_id),
    participants_count: drill || input.kind === "other" ? whole(input.participants_count) : null,
    duration_minutes: drill || input.kind === "other" ? whole(input.duration_minutes) : null,
    result: input.result ?? "ok",
    observations: text(input.observations),
    document_id: text(input.document_id),
  };
}

/** The add / correct policy dialog (FR-COMP-056, FR-COMP-057). */
export const policyFormSchema = z.object({
  title: z.string().min(3, { error: "tooShort" }).max(120, { error: "tooLong" }),
  document_id: z.string().min(1, { error: "chooseOption" }),
  review_due: z.string().optional(),
  ack_roles: z.array(z.string()),
});
export type PolicyInput = z.output<typeof policyFormSchema>;

// --- calls ----------------------------------------------------------------------------------

export async function fetchChecks(api: ApiClient): Promise<ChecksOverview> {
  return call(checksOverviewSchema, loose(api).GET("/api/v1/compliance/checks"));
}

export async function recordCheck(
  api: ApiClient,
  input: CheckInput,
  drill: boolean,
  idempotencyKey: string,
): Promise<CheckEntry> {
  return call(
    checkEntry,
    loose(api).POST("/api/v1/compliance/checks/entries", {
      body: checkBody(input, drill),
      headers: { "Idempotency-Key": idempotencyKey },
    }),
  );
}

export async function removeCheck(api: ApiClient, entry: CheckEntry): Promise<CheckEntry> {
  return call(
    checkEntry,
    loose(api).POST("/api/v1/compliance/checks/entries/{check_id}:remove", {
      params: { path: { check_id: entry.id } },
      headers: { "If-Match": ifMatch(entry.version) },
    }),
  );
}

export async function fetchPolicies(api: ApiClient): Promise<Policies> {
  return call(policiesSchema, loose(api).GET("/api/v1/compliance/policies"));
}

export async function fetchPolicy(api: ApiClient, id: string): Promise<PolicyDetail> {
  return call(
    policyDetailSchema,
    loose(api).GET("/api/v1/compliance/policies/{policy_id}", {
      params: { path: { policy_id: id } },
    }),
  );
}

export async function createPolicy(
  api: ApiClient,
  input: PolicyInput,
  idempotencyKey: string,
): Promise<Policy> {
  return call(
    policySchema,
    loose(api).POST("/api/v1/compliance/policies", {
      body: {
        title: input.title.trim(),
        document_id: input.document_id,
        review_due: text(input.review_due),
        ack_roles: input.ack_roles,
        notify: true,
      },
      headers: { "Idempotency-Key": idempotencyKey },
    }),
  );
}

export async function updatePolicy(
  api: ApiClient,
  policy: Policy,
  input: PolicyInput,
  status: Policy["status"],
): Promise<Policy> {
  return call(
    policySchema,
    loose(api).PUT("/api/v1/compliance/policies/{policy_id}", {
      params: { path: { policy_id: policy.id } },
      body: {
        title: input.title.trim(),
        document_id: input.document_id,
        review_due: text(input.review_due) ?? policy.review_due,
        ack_roles: input.ack_roles,
        status,
      },
      headers: { "If-Match": ifMatch(policy.version) },
    }),
  );
}

/** Retire or bring back a policy: the same PUT with every field unchanged but the status. */
export async function setPolicyStatus(
  api: ApiClient,
  policy: Policy,
  status: Policy["status"],
): Promise<Policy> {
  return updatePolicy(
    api,
    policy,
    {
      title: policy.title,
      document_id: policy.document?.id ?? "",
      review_due: policy.review_due,
      ack_roles: policy.ack_roles.map((r) => r.role),
    },
    status,
  );
}

export async function reviewPolicy(
  api: ApiClient,
  policy: Policy,
  nextReviewDue: string | undefined,
): Promise<Policy> {
  return call(
    policySchema,
    loose(api).POST("/api/v1/compliance/policies/{policy_id}:review", {
      params: { path: { policy_id: policy.id } },
      body: { next_review_due: text(nextReviewDue) },
      headers: { "If-Match": ifMatch(policy.version) },
    }),
  );
}

export async function askAgain(api: ApiClient, policy: Policy): Promise<{ notified: number }> {
  return call(
    z.object({ notified: z.number() }),
    loose(api).POST("/api/v1/compliance/policies/{policy_id}:request-acknowledgement", {
      params: { path: { policy_id: policy.id } },
    }),
  );
}

export async function fetchMyPolicies(api: ApiClient): Promise<MyPolicies> {
  return call(myPoliciesSchema, loose(api).GET("/api/v1/compliance/my-policies"));
}

export async function openMyPolicy(api: ApiClient, id: string): Promise<PolicyFile> {
  return call(
    policyFile,
    loose(api).GET("/api/v1/compliance/my-policies/{policy_id}/file", {
      params: { path: { policy_id: id } },
    }),
  );
}

export async function acknowledgePolicy(
  api: ApiClient,
  id: string,
  documentVersionId: string,
): Promise<MyPolicy> {
  return call(
    myPolicy,
    loose(api).POST("/api/v1/compliance/my-policies/{policy_id}:acknowledge", {
      params: { path: { policy_id: id } },
      body: { document_version_id: documentVersionId },
    }),
  );
}
